// This file was generated by Slater.app - Magnetism.js


const magneticElements = document.querySelectorAll('[data-magnetic]');

magneticElements.forEach((el) => {
  // quickTo pour une performance maximale (60fps+)
  const xTo = gsap.quickTo(el, "x", { duration: 1, ease: "power4.out" });
  const yTo = gsap.quickTo(el, "y", { duration: 1, ease: "power4.out" });

  el.addEventListener("mousemove", (e) => {
    const { clientX, clientY } = e;
    const { width, height, left, top } = el.getBoundingClientRect();

    // Calcul de la position relative par rapport au centre
    // Diviseur à 3 pour un magnétisme légèrement plus présent
    const x = (clientX - (left + width / 2)) / 3;
    const y = (clientY - (top + height / 2)) / 3;

    xTo(x);
    yTo(y);
  });

  el.addEventListener("mouseleave", () => {
    // Retour à la position d'origine avec un lissage soyeux
    xTo(0);
    yTo(0);
  });
});


